setup:
CREATE TABLE customers (
    id integer PRIMARY KEY,
    name text
);
INSERT INTO customers (id, name) VALUES
    (1, 'Ana'),
    (2, 'Ben'),
    (3, 'Cleo');

CREATE TABLE orders (
    id integer PRIMARY KEY,
    customer_id integer,
    ordered_on date
);
INSERT INTO orders (id, customer_id, ordered_on) VALUES
    (1, 1, DATE '2025-03-01'),
    (2, 2, DATE '2025-03-02'),
    (3, 1, DATE '2025-03-05'),
    (4, 3, DATE '2025-03-07');

CREATE TABLE products (
    id integer PRIMARY KEY,
    name text,
    price numeric(10, 2)
);
INSERT INTO products (id, name, price) VALUES
    (1, 'Notebook', 3.50),
    (2, 'Pen', 1.25),
    (3, 'Backpack', 24.00),
    (4, 'Mug', 8.00);

CREATE TABLE order_items (
    order_id integer,
    product_id integer,
    qty integer
);
INSERT INTO order_items (order_id, product_id, qty) VALUES
    (1, 1, 2),
    (1, 2, 5),
    (2, 3, 1),
    (3, 2, 3),
    (3, 4, 2),
    (4, 1, 1),
    (4, 4, 1);

CREATE TABLE staff (
    id integer PRIMARY KEY,
    name text,
    manager_id integer
);
INSERT INTO staff (id, name, manager_id) VALUES
    (1, 'Maya', NULL),
    (2, 'Omar', 1),
    (3, 'Priya', 1),
    (4, 'Liam', 2),
    (5, 'Nora', 2),
    (6, 'Theo', 3);

CREATE TABLE sizes (size text);
INSERT INTO sizes (size) VALUES ('S'), ('M'), ('L');

CREATE TABLE colors (color text);
INSERT INTO colors (color) VALUES ('Black'), ('Red'), ('White');

